        var DESC_JA = "", DESC_EN = "YinYang-Harmony is a tantra massage and healing salon in Umeda, Osaka. A nationally licensed acupuncturist with 30 years of experience offers treatments drawing on breathing, meditation and qigong. By appointment only, about an 8-minute walk from Umeda Station.";
        var metaDesc = document.querySelector('meta[name="description"]');
        if (metaDesc) DESC_JA = metaDesc.getAttribute("content") || "";

        function norm(s) { return (s || "").replace(/\s+/g, ""); }
        var textRecs = [], attrRecs = [];
        (function collect() {
          var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
            acceptNode: function (n) {
              if (!n.nodeValue || !n.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
              var p = n.parentNode;
              if (p && (p.tagName === "SCRIPT" || p.tagName === "STYLE")) return NodeFilter.FILTER_REJECT;
              return NodeFilter.FILTER_ACCEPT;
            }
          });
          var n;
          while ((n = walker.nextNode())) textRecs.push({ node: n, ja: n.nodeValue });
          document.querySelectorAll("img[alt], [placeholder]").forEach(function (el) {
            if (el.hasAttribute("alt")) attrRecs.push({ el: el, attr: "alt", ja: el.getAttribute("alt") });
            if (el.hasAttribute("placeholder")) attrRecs.push({ el: el, attr: "placeholder", ja: el.getAttribute("placeholder") });
          });
        })();

        var btn = document.getElementById("langToggle");
        function apply(lang) {
          var en = lang === "en";
          document.documentElement.setAttribute("lang", en ? "en" : "ja");
          textRecs.forEach(function (r) {
            if (en) { var t = DICT[norm(r.ja)]; if (t !== undefined) r.node.nodeValue = t; }
            else r.node.nodeValue = r.ja;
          });
          attrRecs.forEach(function (r) {
            if (en) { var t = DICT[norm(r.ja)]; if (t !== undefined) r.el.setAttribute(r.attr, t); }
            else r.el.setAttribute(r.attr, r.ja);
          });
          document.title = en ? TITLE_EN : TITLE_JA;
          if (metaDesc) metaDesc.setAttribute("content", en ? DESC_EN : DESC_JA);
          if (btn) {
            btn.textContent = en ? "日本語" : "English";
            btn.setAttribute("aria-pressed", en ? "true" : "false");
          }
        }
        if (btn) {
          btn.addEventListener("click", function () {
            apply(document.documentElement.getAttribute("lang") === "en" ? "ja" : "en");
            window.scrollTo(window.scrollX, window.scrollY);
          });
        }
